 body.userData.anchor=new T.Vector3(0,1.4,0);shell(lathe(body,0,0,0,[[.23,0],[.35,.25],[.35,1.5],[.5,1.65],[.5,2.45],[.35,2.6],[.35,2.95]],colors.steel));cyl(body,.55,.14,0,1.8,0,colors.gold);cyl(body,.55,.14,0,2.4,0,colors.dark);for(const x of [-.55,.55]){box(body,.3,.15,.5,x,1.8,0,colors.steel);cyl(body,.06,.12,x,1.9,0,colors.dark)}
 const plunger=part('unit-plunger','Émbolo y empujador superior',[2,3.45,0],[0,1.4,0],'Desciende por el balancín y comprime el combustible en la camisa.','Balancín → empujador superior → émbolo → cámara de bombeo.','El émbolo se mueve hacia abajo durante la compresión; carrera visual ampliada.');
 const pm=new T.Group();plunger.add(pm);cyl(pm,.12,1.5,0,0,0,colors.gold);cyl(pm,.17,.7,0,1.05,0,colors.dark);cyl(pm,.35,.12,0,1.45,0,colors.gold);motions.push({kind:'unit-plunger',obj:pm});
 const liner=part('unit-liner','Camisa y lumbreras de admisión',[2,2.7,0],[-.7,.3,.3],'Guía el émbolo y contiene las aberturas de llenado y descarga.','Conecta la galería de alimentación con la cámara mientras el émbolo descubre las lumbreras.','Diapositiva 61, elemento 4. Las lumbreras se resaltan en azul; hélices y taladros simplificados.',true);shell(cyl(liner,.24,1.6,0,0,0,colors.body));for(const x of [-.24,.24])cyl(liner,.085,.08,x,0,0,colors.feed,'x');
 const springPart=part('unit-spring','Resorte de recuperación',[2,4.35,0],[0,2.2,0],'Recupera el émbolo cuando el mando mecánico deja de empujarlo.','Entre el cuerpo y la cabeza del empujador superior.','Se representa su compresión en sincronía con el émbolo.');const sp=new T.Group();springPart.add(sp);spring(sp,0,0,0,.27,.5);motions.push({kind:'unit-spring',obj:sp});
 const rocker=part('unit-rocker','Balancín',[.5,5.02,0],[0,1.7,.5],'Invierte el movimiento: la varilla sube y el extremo sobre el inyector baja.','Varilla de empuje → balancín → émbolo del inyector-bomba.','Apoyo central esquemático de la diapositiva 28.');const rm=new T.Group();rocker.add(rm);box(rm,3.15,.17,.28,0,0,0,colors.gold);cyl(rocker,.2,.6,0,0,0,colors.dark,'z');cyl(rm,.16,.2,1.5,0,0,colors.steel,'z');motions.push({kind:'unit-rocker',obj:rm});
 const rod=part('unit-rod','Varilla y seguidor de leva',[-1,3.28,0],[-1,.2,.3],'Transmite la elevación de la leva al balancín.','Leva → rodillo seguidor → varilla → balancín.','Figura 443, elemento 6.');const rodm=new T.Group();rod.add(rodm);cyl(rodm,.075,3.35,0,0,0,colors.steel);cyl(rodm,.18,.22,0,-1.72,0,colors.dark,'z');motions.push({kind:'unit-rod',obj:rodm});
 const cam=part('unit-cam','Leva de accionamiento',[-1,.86,0],[-1,-.3,.3],'Transforma el giro del árbol en elevación del seguidor.','Accionamiento del motor → leva → seguidor.','Perfil didáctico con alzada visible; no corresponde a un reglaje de fabricación.');
 const cm=new T.Group();cam.add(cm);const shape=new T.Shape();for(let i=0;i<=64;i++){const a=i/64*Math.PI*2,c=((a-Math.PI/2+Math.PI*2)%(Math.PI*2))/(Math.PI/2),l=c<1?0:c<2?c-1:c<3?1:4-c,rad=.52+.3*l,x=rad*Math.cos(a),y=rad*Math.sin(a);if(i===0)shape.moveTo(x,y);else shape.lineTo(x,y)}mesh(cm,new T.ExtrudeGeometry(shape,{depth:.24,bevelEnabled:true,bevelThickness:.04,bevelSize:.03,bevelSegments:2}),colors.gold,0,0,-.12);cyl(cam,.13,.8,0,0,0,colors.dark,'z');motions.push({kind:'unit-cam',obj:cm});
 const rack=part('unit-rack','Cremallera de regulación',[2,3.65,.56],[1.3,.4,.9],'Modifica el giro del elemento de regulación para variar la cantidad entregada.','Mando de regulación → cremallera → engranaje → émbolo.','Figura 443, elemento 5; diapositiva 61, elemento 3. Posición fija de estudio.');box(rack,1.9,.12,.12,0,0,0,colors.gold);for(let i=0;i<13;i++)box(rack,.05,.12,.06,-.8+i*.13,0,-.1,colors.gold);
 const pinion=part('unit-pinion','Engranaje de regulación',[2,3.65,0],[.8,.6,.8],'Transmite al émbolo el ajuste angular indicado por la cremallera.','Engrana con la cremallera de mando.','Diapositiva 61, elemento 2; no gira continuamente con la leva.',true);const pg=gear(pinion,0,0,0,.3);pg.rotation.x=Math.PI/2;
 const filters=part('unit-filter','Filtros de la unidad',[2,3.98,0],[1.2,.7,0],'Retienen partículas en las conexiones del propio inyector-bomba.','Alimentación y retorno del cuerpo.','Diapositiva 61, elemento 7; distintos del filtro principal.');for(const x of [-.58,.58]){cyl(filters,.15,.4,x,0,0,colors.gold);for(let i=0;i<5;i++)cyl(filters,.16,.025,x,-.15+i*.07,0,colors.dark)}
 const flat=part('unit-flat','Válvula de asiento plano',[2,1.9,0],[0,-.35,.8],'Forma parte del cierre del paso hacia el pulverizador.','Entre la cámara de bombeo y el conjunto inferior.','Diapositiva 61, elemento 5; apertura didáctica ampliada.',true);const fm=cyl(flat,.17,.065,0,0,0,colors.gold);motions.push({kind:'unit-valve',obj:fm});
 const ball=part('unit-ball','Válvula de asiento esférico',[2,1.7,0],[0,-.7,.8],'Participa en el cierre del conjunto inferior del inyector.','Bajo la válvula de asiento plano, antes de la boquilla.','Diapositiva 61, elemento 6; no se reproduce el detalle de sus asientos.',true);const bm=mesh(ball,new T.SphereGeometry(.09,24,16),colors.steel);motions.push({kind:'unit-valve',obj:bm});
