 const nozzle=part('unit-nozzle','Boquilla pulverizadora',[2,1.1,0],[0,-1.1,.1],'Introduce el combustible pulverizado en la cámara de combustión.','Conjunto de válvulas → boquilla → cilindro.','Diapositiva 61, elemento 9. El cono naranja representa combustible pulverizado.');lathe(nozzle,0,0,0,[[.08,0],[.16,.08],[.24,.27],[.28,.37]],colors.dark);for(let i=0;i<6;i++){const a=i*Math.PI/3;mesh(nozzle,new T.SphereGeometry(.025,8,6),0x111111,.12*Math.cos(a),.06,.12*Math.sin(a))}
