 pipe('unit-feed','Alimentación a baja presión',[[-4.1,2.6,.6],[-3,3.5,-.5],[.7,3.98,-.5],[1.42,3.98,0]],'feed','Lleva el combustible filtrado al cuerpo del inyector-bomba; no es una línea de alta presión.');
 pipe('unit-return','Retorno al depósito',[[2.58,3.98,0],[3.4,3.98,0],[3.4,.7,1.3],[-4.3,.7,1.3]],'back','Devuelve el excedente de la unidad al depósito.');
