 const rings=ep('rings','Aros de pistón',[0,0,0],[0,.25,1.6],'Sellan los gases y controlan el aceite sobre la camisa.','Alojados en ranuras alrededor de la corona y falda superior.');rings.userData.anchor=new T.Vector3(cx,tip-.6,z);
 const rods=ep('rods','Bielas y bulones',[0,0,0],[0,-.3,1.4],'Transmiten el esfuerzo del pistón a las muñequillas del cigüeñal.','Bulón arriba; cabeza de biela sobre la muñequilla abajo.');rods.userData.anchor=new T.Vector3(cx,tip-1.8,z);
 const crank=ep('crank','Cigüeñal y contrapesos',[0,cy,z],[0,-1,0],'Convierte el movimiento alternativo en rotación.','Muñequillas → bielas; apoyos principales → bancada; salida → volante.');crank.userData.anchor=new T.Vector3(cx,0,0);
 const bearings=ep('bearings','Bancada y cojinetes',[cx,cy,z],[0,-.65,-.8],'Sostienen el eje del cigüeñal y permiten su giro con lubricación.','Apoyos del cigüeñal dentro del block.');
 const anchors=[];
