  const piston=new T.Group();pistons.add(piston);lathe(piston,0,-.25,0,[[.47,0],[.48,.5],[.3,.5],[.24,.36],[0,.36]],0xbbc3c3);
  const ringGroup=new T.Group();rings.add(ringGroup);for(const dy of [.08,.16,.23]){const m=mesh(ringGroup,new T.TorusGeometry(.48,.02,6,32),colors.dark,0,dy,0);m.rotation.x=Math.PI/2}
