  const big=cyl(rods,.22,.22,x,0,z,colors.steel,'x');
  const counterweights=[];const throwGroup=new T.Group();throwGroup.position.x=x;crank.add(throwGroup);
  cyl(throwGroup,.14,.48,0,.5,0,colors.gold,'x');
  for(const dx of [-.3,.3]){box(throwGroup,.12,.8,.2,dx,.15,0,colors.dark);counterweights.push(cyl(throwGroup,.30,.14,dx,-.30,0,colors.steel,'x'))}
