   const lever=new T.Group();lever.position.set(vx,tip+.82,(vz+pz)/2);rk.add(lever);box(lever,.10,.06,vz-pz,0,0,0,colors.gold);cyl(lever,.06,.18,0,0,0,colors.dark,'x');
   cyl(pr,.03,tip+.8-(cy+.7),vx,(tip+.8+cy+.7)/2,pz,colors.steel);cyl(tp,.09,.23,vx,cy+.65,pz,colors.dark);
