 engineMoving[0].flywheel=flywheel;
 const cover=ep('cover','Tapa de balancines',[cx,tip+1.05,z],[0,2.5,0],'Protege el mecanismo de válvulas y contiene salpicaduras de lubricante.','Sobre los balancines, con aberturas alrededor de los inyectores.');for(const side of [-1,1])shell(box(cover,w,.3,.09,0,0,side*.72,0x708d8a));
