function updateMotion(){animateEngine();const engineOn=$('#engine-toggle').checked,cycle=(phase+(engineOn?2:0))%4,idx=system==='unitario'?0:(engineOn?Math.round(phase/4):Math.floor(phase/4))%4,stage=Math.floor(cycle),lift=stage===1?(cycle-1):stage===2?1:stage===3?1-(cycle-3):0;const delivering=(engineOn?engineState.some(c=>c.inject):stage===2)&&explosion===0&&!$('#isolate').checked;
 for(const m of motions){const active=engineOn?(engineState[m.i]?.inject||false):m.i===idx;
 if(m.kind==='radial-rotor')m.obj.rotation.z=(idx+(stage===3?cycle-3:0))*Math.PI/2;
 if(m.kind==='radial-plunger')m.obj.position.x=m.sign*(.47-.18*lift);
 if(m.kind==='rail-pump')m.obj.position.y=-.3+Math.sin(cycle*Math.PI/2)*.18;
 if(m.kind==='rail-valve'){m.obj.position.copy(m.base);m.obj.position.y+=active&&(engineOn||stage===2)?.1:0}
 if(m.kind==='rail-relief')m.obj.position.y=-.2+(stage===3?.12:0);

 if(m.kind==='unit-plunger')m.obj.position.y=-lift*.3;
 if(m.kind==='unit-rod')m.obj.position.y=lift*.3;
 if(m.kind==='unit-rocker')m.obj.rotation.z=-Math.asin(lift*.2);
 if(m.kind==='unit-spring')m.obj.scale.y=1-lift*.6;
 if(m.kind==='unit-valve')m.obj.position.y=(engineOn?engineState[0].inject:stage===2)?-.04:0;
 if(m.kind==='unit-cam')m.obj.rotation.z=-cycle*Math.PI/2;
 if(m.kind==='gear')m.obj.rotation.z=phase*.7*m.sign;if(m.kind==='rotor')m.obj.rotation.z=(idx+(stage===3?cycle-3:0))*Math.PI/2;if(m.kind==='cam')m.obj.rotation.x=phase*Math.PI/2+m.i*Math.PI/2;if(['plunger','needle','poppet'].includes(m.kind)){m.obj.position.copy(m.base);m.obj.position.y+=(m.kind==='plunger'?(active?lift*.24:0):(active&&stage===2?.12:0))}if(m.kind==='rocker')m.obj.rotation.z=active&&stage===2?-.16:0;}
 for(const p of pipes){p.dot.visible=explosion===0&&!$('#isolate').checked&&(p.type!=='high'||p.g.userData.continuous||(p.index<0?stage>0:delivering&&(engineOn?engineState[p.index]?.inject:p.index===idx)))&&(!p.g.userData.relief||stage===3);p.dot.position.copy(p.path.getPointAt((phase*.65)%1));p.mesh.material.emissive.setHex(p.type==='high'&&(p.g.userData.continuous||delivering&&p.index===idx)?colors.high:0);p.mesh.material.emissiveIntensity=.5}
 sprays.forEach(s=>{s.obj.visible=delivering&&(engineOn?engineState[s.i].inject:s.i===idx);if(s.obj.userData.originalY===undefined)s.obj.userData.originalY=s.obj.position.y;const on=$('#engine-toggle').checked;s.obj.scale.y=on?Math.min(.5,engineState[s.i].clearance*.85)/ (system==='unitario'?.7:.65):1;const top=system==='unitario'?1.1:3.45;s.obj.position.y=on?top-s.obj.scale.y*(system==='unitario'?.7:.65)/2:s.obj.userData.originalY;});const ph=systems[system].phases[stage];$('#phase-number').textContent=String(stage+1).padStart(2,'0');$('#phase-title').textContent=ph[0]+' · cilindro '+(idx+1);$('#phase-description').textContent=ph[1];if(engineOn){$('#phase-number').textContent='2T';$('#phase-title').textContent=$('#engine-status').textContent;$('#phase-description').textContent='Una vuelta del cigüeñal completa el ciclo. Azul: aire; naranja: combustión tras la inyección; gris: gases de escape. Las lumbreras se abren al quedar debajo de la corona del pistón.';}
}
function drawLabels(){
 const w=$('#scene').clientWidth,h=$('#scene').clientHeight,used=[];
 for(const {p,el,line} of [...labels].sort((a,b)=>Number(b.p.id===selected)-Number(a.p.id===selected))){
  line.style.display='none';const focus=hovered||selected;el.hidden=!(namesMode!=='off'&&p.g.visible&&(namesMode==='hover'?p.id===focus:(!p.g.userData.pipe||p.id===selected)&&(!p.internal||p.id===selected||explosion>.1)&&(!p.g.userData.engine||p.id===selected||explosion>.1||['engine-head','engine-block','engine-crank','engine-exhaust'].includes(p.id))));if(el.hidden)continue;
  const v=(p.g.userData.anchor||new T.Vector3(0,.55,0)).clone();p.g.localToWorld(v);v.project(camera);
  const ax=(v.x*.5+.5)*w,ay=(-v.y*.5+.5)*h;
  if(v.z>1||v.z< -1||ax<0||ax>w||ay<0||ay>h){el.hidden=true;continue}
  const bw=el.offsetWidth||150,bh=el.offsetHeight||25;let chosen;
  for(const dy of [0,-30,30,-60,60,-90,90,-120,120,-150,150,-180,180]){
   for(const dx of [0,-160,160,-300,300]){
    const x=Math.max(6,Math.min(w-bw-6,ax-bw/2+dx)),y=Math.max(6,Math.min(h-bh-6,ay-bh+dy)),r={x,y,w:bw,h:bh};
    if(!used.some(o=>x<o.x+o.w+4&&x+bw>o.x-4&&y<o.y+o.h+4&&y+bh>o.y-4)){chosen=r;break}
   }if(chosen)break;
  }
  if(!chosen){el.hidden=true;continue}used.push(chosen);const x=chosen.x+bw/2,y=chosen.y+bh;el.style.left=x+'px';el.style.top=y+'px';line.style.display='';line.setAttribute('d','M '+ax+' '+ay+' L '+x+' '+y);
 }
}
