 $('#engine-toggle').onchange=()=>{if(!$('#engine-toggle').checked)$('#engine-cut').checked=false;if(!$('#engine-toggle').checked&&selected.startsWith('engine-'))choose(system==='unitario'?'unit-body':'injectors');applyView();resetView()};
