 function pick(e){const r=$('#canvas').getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);scene.updateMatrixWorld(true);const hits=ray.intersectObjects(parts.filter(p=>p.g.visible).map(p=>p.g),true);for(const hit of hits){let o=hit.object,visible=true;for(let q=o;q;q=q.parent)if(!q.visible)visible=false;if(!visible||(o.material?.clippingPlanes||[]).some(plane=>plane.distanceToPoint(hit.point)<0))continue;while(o&&!o.userData.id)o=o.parent;if(o)return o.userData.id;}return '';}
 $('#names').onclick=()=>{namesMode=namesMode==='all'?'hover':namesMode==='hover'?'off':'all';hovered='';$('#names').textContent=namesMode==='hover'?'Nombres con selección':namesMode==='off'?'Nombres desactivados':'Nombres';$('#names').dataset.mode=namesMode;$('#names').setAttribute('aria-pressed',String(namesMode!=='off'));lastRenderState='';};
